@Tags(['regression', 'slow'])
// Regression test for issue #349.
//
// `zfa entity create --allow-forward-refs --field url:WebUri?` emitted:
//   1. A `$`-prefixed type `$WebUri` — wrong for external (non-entity) types
//      that are never generated by zorphy.
//   2. A bogus import `import '../web_uri/web_uri.dart';` for a directory
//      that does not exist, or `import '../enums/index.dart';` for a type
//      that is not an enum.
//
// Root cause: `FieldNormalizer._determinePrefix()` returned `$` for any
// type without an on-disk entity file, assuming it was a forward-ref entity.
// `ImportResolver` assumed any non-primitive, non-entity type was an enum
// and added `enums/index.dart`. There was no way to declare a type as
// external (never an entity, never an enum).
//
// Fix (this PR): the `!Type` prefix syntax marks a field type as external.
// `--field url:!WebUri?` keeps `WebUri?` as-is (no `$` prefix, no validation,
// no import emission). This works both with and without `--allow-forward-refs`.
//
// This test locks in the fix end-to-end by spawning the `zfa` CLI binary
// against a temp workspace.

import 'dart:io';

import 'package:path/path.dart' as p;
import 'package:test/test.dart';

/// Resolve package root at discovery time, before any test changes CWD.
final _zfaRoot = Directory.current.path;

void main() {
  group('#349 — !Type prefix for external (non-entity) types', () {
    late Directory workspace;
    late String zfaBin;
    late bool zorphyAvailable;

    Future<ProcessResult> runZfa(List<String> args) {
      return Process.run('dart', [
        zfaBin,
        ...args,
      ], workingDirectory: workspace.path);
    }

    setUp(() async {
      zfaBin = p.join(_zfaRoot, 'bin', 'zfa.dart');
      workspace = await Directory.systemTemp.createTemp('issue_349_');
      // Local zorphy checkouts via path deps (mirrors zuraffa's own
      // dependency_overrides and the #351 regression test). When the
      // sibling zorphy repo is absent (CI), the codegen test below skips
      // and the pubspec falls back to the same git refs zuraffa's own
      // pubspec.yaml uses instead of emitting unresolvable path deps; the
      // CLI-level assertions still run.
      final repoRoot = p.normalize(p.join(_zfaRoot, '..'));
      final zorphyPath = p.normalize(p.join(repoRoot, 'zorphy', 'zorphy'));
      final zorphyAnnotationPath = p.normalize(
        p.join(repoRoot, 'zorphy', 'zorphy_annotation'),
      );
      zorphyAvailable =
          Directory(zorphyPath).existsSync() &&
          Directory(zorphyAnnotationPath).existsSync();
      final zorphyDeps = zorphyAvailable
          ? '''
  zorphy:
    path: $zorphyPath
  zorphy_annotation:
    path: $zorphyAnnotationPath'''
          : '''
  zorphy:
    git:
      url: https://github.com/arrrrny/zorphy.git
      path: zorphy
      ref: "fix/349-external-type-no-dollar-prefix-cli"
  zorphy_annotation:
    git:
      url: https://github.com/arrrrny/zorphy.git
      path: zorphy_annotation
      ref: "development"''';
      await File(p.join(workspace.path, 'pubspec.yaml')).writeAsString('''
name: issue_349_test_app
environment:
  sdk: '>=3.12.0 <4.0.0'
dependencies:
$zorphyDeps
  json_annotation: ^4.12.0
dev_dependencies:
  build_runner: ^2.4.0
  json_serializable: ^6.13.0
  analyzer: '14.1.0'
dependency_overrides:
$zorphyDeps
  analyzer: '14.1.0'
''');
      await File(p.join(workspace.path, 'build.yaml')).writeAsString('''
targets:
  \$default:
    builders:
      zorphy:zorphy:
        enabled: true
        generate_for:
          - lib/**
      json_serializable:json_serializable:
        enabled: true
        generate_for:
          - lib/**
''');
    });

    tearDown(() async {
      if (workspace.existsSync()) {
        await workspace.delete(recursive: true);
      }
    });

    test(
      'external type WITH ! prefix keeps type as-is, no bogus import',
      timeout: const Timeout(Duration(minutes: 2)),
      () async {
        final result = await runZfa([
          'entity',
          'create',
          '-n',
          'JsAlertRequest',
          '--kind=value_object',
          '--field',
          'url:!WebUri?',
          '--field',
          'message:String?',
          '--allow-forward-refs',
        ]);

        expect(
          result.exitCode,
          equals(0),
          reason: '! prefix must be accepted with --allow-forward-refs',
        );

        final entityFile = File(
          p.join(
            workspace.path,
            'lib',
            'src',
            'domain',
            'entities',
            'js_alert_request',
            'js_alert_request.dart',
          ),
        );
        expect(entityFile.existsSync(), isTrue);

        final content = await entityFile.readAsString();

        // The type must be `WebUri?`, NOT `$WebUri?`.
        expect(
          content,
          contains('WebUri? get url'),
          reason: '! prefix must keep the type name as-is without \$ prefix',
        );
        expect(
          content,
          isNot(contains('\$WebUri')),
          reason: 'External type must NOT be \$-prefixed',
        );

        // No bogus entity import for the external type.
        expect(
          content,
          isNot(contains("import '../web_uri/web_uri.dart';")),
          reason: 'No entity-style import for external types',
        );

        // No bogus enum import either.
        expect(
          content,
          isNot(contains("import '../enums/index.dart';")),
          reason: 'No enum import for external types',
        );
      },
    );

    test(
      'external type WITH ! prefix but WITHOUT --allow-forward-refs is accepted',
      timeout: const Timeout(Duration(minutes: 2)),
      () async {
        final result = await runZfa([
          'entity',
          'create',
          '-n',
          'JsAlertRequest',
          '--kind=value_object',
          '--field',
          'url:!WebUri?',
          '--field',
          'message:String?',
        ]);

        expect(
          result.exitCode,
          equals(0),
          reason:
              '! prefix must bypass on-disk validation even without --allow-forward-refs',
        );

        final entityFile = File(
          p.join(
            workspace.path,
            'lib',
            'src',
            'domain',
            'entities',
            'js_alert_request',
            'js_alert_request.dart',
          ),
        );
        expect(entityFile.existsSync(), isTrue);

        final content = await entityFile.readAsString();

        expect(content, contains('WebUri? get url'));
        expect(content, isNot(contains('\$WebUri')));
        expect(content, isNot(contains("import '../web_uri/web_uri.dart';")));
        expect(content, isNot(contains("import '../enums/index.dart';")));
      },
    );

    test(
      'add-field with ! prefix adds external type without \$ prefix',
      timeout: const Timeout(Duration(minutes: 2)),
      () async {
        final create = await runZfa([
          'entity',
          'create',
          '-n',
          'JsAlertRequest',
          '--kind=value_object',
          '--field',
          'message:String?',
        ]);
        expect(create.exitCode, equals(0));

        final add = await runZfa([
          'entity',
          'add-field',
          '-n',
          'JsAlertRequest',
          '--field',
          'url:!WebUri?',
        ]);
        expect(
          add.exitCode,
          equals(0),
          reason: '! prefix must be accepted for add-field',
        );

        final entityFile = File(
          p.join(
            workspace.path,
            'lib',
            'src',
            'domain',
            'entities',
            'js_alert_request',
            'js_alert_request.dart',
          ),
        );
        expect(entityFile.existsSync(), isTrue);

        final content = await entityFile.readAsString();

        expect(
          content,
          contains('WebUri? get url'),
          reason: 'External type must not be \$-prefixed in add-field',
        );
        expect(content, isNot(contains('\$WebUri')));
      },
    );

    test(
      'external type compiles when user manually adds required import',
      timeout: const Timeout(Duration(minutes: 2)),
      () async {
        // Codegen test: `dart pub get` below needs the local zorphy
        // checkouts behind the path deps to exist. Skip when they are
        // absent (CI without a sibling zorphy repo) — same pattern as the
        // #351 regression test; the CLI-level assertions still run.
        if (!zorphyAvailable) {
          print(
            'Skipping: local zorphy checkout not found at ../zorphy '
            '(CI without a sibling zorphy repo).',
          );
          return;
        }

        // Create entity with external WebUri type
        final createResult = await runZfa([
          'entity',
          'create',
          '-n',
          'JsAlertRequest',
          '--kind=value_object',
          '--field',
          'url:!WebUri?',
          '--field',
          'message:String?',
        ]);

        expect(createResult.exitCode, equals(0));

        final entityFile = File(
          p.join(
            workspace.path,
            'lib',
            'src',
            'domain',
            'entities',
            'js_alert_request',
            'js_alert_request.dart',
          ),
        );
        expect(entityFile.existsSync(), isTrue);

        var content = await entityFile.readAsString();

        // Verify external type is present without $ prefix
        expect(content, contains('WebUri? get url'));
        expect(content, isNot(contains('\$WebUri')));

        // Manually add the required import for WebUri (simulating what user
        // must do — the documented workflow). Since we don't actually have
        // webview_flutter package, we'll create a mock WebUri class in the
        // workspace to make the code analyzable. Also add the standard
        // @JsonKey fromJson/toJson glue that the migration recipe applies to
        // non-JSON-native field types (WebUri is a custom class — plain
        // json_serializable semantics require the glue; the #349 contract is
        // that the TYPE resolves at build time instead of InvalidType).
        final mockWebUriDir = Directory(
          p.join(workspace.path, 'lib', 'src', 'external'),
        );
        await mockWebUriDir.create(recursive: true);

        final mockWebUriFile = File(p.join(mockWebUriDir.path, 'web_uri.dart'));
        await mockWebUriFile.writeAsString('''
/// Mock WebUri class for testing external type references
class WebUri {
  final String uri;
  const WebUri(this.uri);

  @override
  String toString() => uri;
}
''');

        // Add the import to the generated entity file (correct relative path:
        // entity is at lib/src/domain/entities/<snake>/, mock at
        // lib/src/external/ -> three levels up).
        final lastImportMatch = RegExp(
          r'^import .*;',
          multiLine: true,
        ).allMatches(content).toList();

        if (lastImportMatch.isEmpty) {
          content = "import '../../../external/web_uri.dart';\n\n$content";
        } else {
          final insertPos = lastImportMatch.last.end;
          content =
              "${content.substring(0, insertPos)}\nimport '../../../external/web_uri.dart';${content.substring(insertPos)}";
        }

        // Add the standard @JsonKey glue for the custom (non-JSON-native)
        // WebUri type — the documented migration recipe. Before the #349
        // fix, the type did not even resolve (`InvalidType`); now it does,
        // and json_serializable only needs the normal glue.
        content = content.replaceFirst(
          'WebUri? get url;',
          '@JsonKey(fromJson: _webUriFromJson, toJson: _webUriToJson)\n'
              '  WebUri? get url;',
        );
        content += '''
WebUri? _webUriFromJson(Object? value) =>
    value == null ? null : WebUri(value as String);

Object? _webUriToJson(WebUri? value) => value?.toString();
''';

        await entityFile.writeAsString(content);

        // Resolve deps + run build_runner so the `.zorphy.dart`/`.g.dart`
        // parts exist (same pattern as the #351 regression test).
        final pubGet = await Process.run('dart', [
          'pub',
          'get',
        ], workingDirectory: workspace.path);
        expect(
          pubGet.exitCode,
          equals(0),
          reason: 'dart pub get failed: ${pubGet.stdout}${pubGet.stderr}',
        );

        final build = await Process.run('dart', [
          'run',
          'build_runner',
          'build',
          '--delete-conflicting-outputs',
        ], workingDirectory: workspace.path);
        expect(
          build.exitCode,
          equals(0),
          reason:
              'build_runner failed for entity with external type:\n'
              '${build.stdout}${build.stderr}',
        );

        // Run dart analyze to verify the generated code compiles
        final analyzeResult = await Process.run('dart', [
          'analyze',
          '--fatal-infos',
          entityFile.path,
        ], workingDirectory: workspace.path);

        expect(
          analyzeResult.exitCode,
          equals(0),
          reason:
              'Generated code with external type should compile when import is added.\n'
              'stdout: ${analyzeResult.stdout}\n'
              'stderr: ${analyzeResult.stderr}',
        );
      },
    );

    test(
      'zfa binary is runnable (smoke)',
      timeout: const Timeout(Duration(minutes: 2)),
      () async {
        final result = await Process.run('dart', [
          zfaBin,
          '--help',
        ], workingDirectory: _zfaRoot);
        expect(result.exitCode, equals(0));
      },
    );
  });
}
